package com.johnny.hotel.cashier;import com.johnny.hotel.entity.*;import com.johnny.hotel.mapper.*;import lombok.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.*;
@Component@RequiredArgsConstructor public class CashierAccess{private final SysUserMapper users;private final SysRoleMapper roles;public record Actor(Long id,Set<String>roles){boolean has(String x){return roles.contains(x);}}
 public Actor actor(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||!(a.getDetails()instanceof Long id))throw denied();var u=users.selectById(id);if(u==null||!Integer.valueOf(1).equals(u.getStatus()))throw denied();var r=roles.selectRolesByUserId(id).stream().map(SysRole::getRoleCode).collect(Collectors.toSet());if(r.contains("CUSTOMER")||r.contains("HR_ADMIN")||r.stream().noneMatch(Set.of("STAFF","MANAGER","FINANCE","OWNER","SUPER_ADMIN")::contains))throw denied();return new Actor(id,r);}
 void staff(Actor a){if(a.roles().stream().noneMatch(Set.of("STAFF","MANAGER","OWNER","SUPER_ADMIN")::contains))throw denied();}void finance(Actor a){if(a.roles().stream().noneMatch(Set.of("FINANCE","OWNER","SUPER_ADMIN")::contains))throw denied();}void oversight(Actor a){if(a.roles().stream().noneMatch(Set.of("MANAGER","FINANCE","OWNER","SUPER_ADMIN")::contains))throw denied();}private AccessDeniedException denied(){return new AccessDeniedException("Cashier access denied");}
}
